mapper.select:
SELECT epic_skill_data.*,
       CASE WHEN user_epic_skill_data.user_epic_skill_idx IS NULL THEN 'N' ELSE 'Y' END AS have_yn
FROM epic_skill_data
         LEFT JOIN user_epic_skill_data
                   ON epic_skill_data.epic_skill_idx = user_epic_skill_data.user_epic_skill_idx
                       AND user_epic_skill_data.user_epic_skill_grade = #{user_epic_skill_grade}
                       AND user_epic_skill_data.use_yn = 'Y'
                       AND user_epic_skill_data.user_uuid = #{user_uuid}
WHERE epic_skill_data.epic_skill_grade = #{epic_skill_grade}
  AND (CASE WHEN user_epic_skill_data.user_epic_skill_idx IS NULL THEN 'N' ELSE 'Y' END) = 'N';
